const clubs=[
{id:'fisher',name:'Fisher Island Club',area:'Fisher Island',type:'Private island club',tags:['Beach','Wellness'],lat:25.7584,lng:-80.1398,image:'https://wp-vg6gw1p28k.pairsite.com/wp-content/uploads/2023/09/Bottom-Image-Beach-Gradient-Splash.webp',gallery:'https://wp-vg6gw1p28k.pairsite.com/wp-content/uploads/2023/09/Bottom-MainImage-GradTo-SplashBottom.webp',description:'An island apart. Secluded sands, a storied Vanderbilt estate, and the unhurried rhythm of life on the water.',membership:'Equity membership · Property ownership required',info:'Equity membership is available to Fisher Island property owners. Contact the club directly for current eligibility and access. The island is reached by ferry or private yacht.',amenities:['Private beach','Golf','Racquet sports','Spa','Marinas'],atmosphere:'Secluded, residential, and quietly refined. A world of its own across Biscayne Bay.',url:'https://fisherislandclub.com/membership-page/',address:'1 Fisher Island Drive, Fisher Island'},
{id:'bath',name:'The Bath Club',area:'Mid-Beach',type:'Private beach club',tags:['Beach','Social'],lat:25.8392,lng:-80.1205,gallery:'https://cdn.prod.website-files.com/68e799deaf7114d8639ee45d/68ea76ff4ca86e7bfa31f9d7_Rectangle.jpg',image:'https://images.squarespace-cdn.com/content/v1/5264308ce4b0469f6989fa93/1579029788487-U9A3CKNC8QQZFBHPESRT/bath-house-exterior-image.jpg',description:'A quieter stretch of Miami Beach. A restored 1920s estate, lush gardens, and more than three acres of members-only beachfront.',membership:'Private membership · Inquire with the club',info:'The Bath Club intentionally limits its membership. Applications, eligibility, and current availability are handled directly by the club.',amenities:['Private beach','Dining','Gardens','Historic estate'],atmosphere:'Intimate and understated, with the charm of old Miami and space to slow down.',url:'https://www.thebathclub.com/about',address:'5937 Collins Avenue, Miami Beach'},
{id:'surf',name:'The Surf Club',area:'Surfside',type:'Historic social club',tags:['Beach','Social','Wellness'],lat:25.8771,lng:-80.1223,image:'https://thesurfclub.com/images/home/1.jpg',gallery:'https://thesurfclub.com/images/home/2.jpg',description:'Old-world glamour on the Atlantic. A legendary Surfside address where a 1930s story meets a new generation of coastal elegance.',membership:'Private club · Separate membership inquiry',info:'Private club membership has its own inquiry process. A hotel or restaurant reservation does not confer private club membership.',amenities:['Oceanfront setting','Dining','Historic architecture','Hotel & residences'],atmosphere:'Gracious and sophisticated. Historic Mediterranean architecture meets contemporary oceanfront living.',url:'https://thesurfclub.com/club-membership-inquiry.php',address:'9011 Collins Avenue, Surfside'},
{id:'soho',name:'Soho Beach House',area:'Mid-Beach',type:'Creative members’ house',tags:['Beach','Social','Wellness'],lat:25.8124,lng:-80.1227,image:'https://media.fastly.sohohousedigital.com/f_auto,q_auto,fl_progressive:steep/t_dc_base/sitecore-prod/images/dotcom-sites/house-pages/miami-beach-house/2025-refresh/december/beach_house_1.png',description:'A meeting place for creative minds. Art Deco character, Cuban-inspired interiors, and long afternoons by the ocean.',membership:'Members’ house · Application required',info:'Membership applications are managed by Soho House. Cecconi’s restaurant welcomes the public; Cowshed spa is members-only. Confirm access directly before visiting.',amenities:['Private beach','Pool','Gym','Cowshed spa','Rooftop'],atmosphere:'Sociable, creative, and relaxed, inside a 1940s beachfront tower.',url:'https://www.sohohouse.com/en-us/houses/soho-beach-house',address:'4385 Collins Avenue, Miami Beach'}];
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];let active='fisher',filter='All clubs',map,markers={},chatBusy=false;let saved=[],prefs={interest:'All clubs',notifications:false,suggestions:true,settingsVersion:2};try{saved=JSON.parse(localStorage.getItem('ostra-saved')||'[]');const storedPrefs=JSON.parse(localStorage.getItem('ostra-prefs')||'{}');prefs={...prefs,...storedPrefs};if(storedPrefs.settingsVersion!==2)prefs={...prefs,interest:'All clubs',settingsVersion:2}}catch{}if(!Array.isArray(saved))saved=[];saved=saved.filter(id=>clubs.some(c=>c.id===id));
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const current=()=>clubs.find(c=>c.id===active);const results=()=>clubs.filter(c=>(filter==='All clubs'||c.tags.includes(filter))&&[c.name,c.area,c.type,...c.tags].join(' ').toLowerCase().includes($('#nav-search').value.toLowerCase().trim()));
function persist(){try{localStorage.setItem('ostra-saved',JSON.stringify(saved));localStorage.setItem('ostra-prefs',JSON.stringify(prefs))}catch{toast('Storage unavailable. Changes last for this visit.')}}
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),2500)}
function save(id){saved=saved.includes(id)?saved.filter(x=>x!==id):[...saved,id];persist();render();$$('[data-save]').forEach(b=>{b.textContent=saved.includes(b.dataset.save)?'♥':'♡';b.setAttribute('aria-pressed',saved.includes(b.dataset.save))});if($('#overlay').dataset.view==='saved')showSaved();toast(saved.includes(id)?'Added to your collection':'Removed from your collection')}
function saveButton(c){return `<button class="save-button" data-save="${c.id}" aria-label="Save ${c.name}" aria-pressed="${saved.includes(c.id)}">${saved.includes(c.id)?'♥':'♡'}</button>`}
function render(){const list=results();if(list.length&&!list.some(c=>c.id===active))active=list[0].id;$('#saved-count').textContent=saved.length;$('#map-count').textContent=list.length;$('#club-content').innerHTML=list.length?`<div class="results-heading"><strong>${list.length} private clubs in Miami</strong><span>Hover a card to locate it</span></div><div class="club-grid">${list.map(c=>`<article class="club-tile ${c.id===active?'active':''}" data-tile="${c.id}" tabindex="0"><div class="tile-photo"><img src="${c.image}" alt="${c.name} coastal setting">${saveButton(c)}</div><div class="tile-title"><h2>${c.name}</h2><span>✧</span></div><div class="meta">${c.area} · ${c.type}</div><p>${c.description}</p><div class="tile-bottom"><span>${c.membership}</span><button data-detail="${c.id}" aria-label="Explore ${c.name}">Explore ↗</button></div></article>`).join('')}</div>`:`<div class="no-results"><h2>No clubs found</h2><p>Try a different search or filter.</p><button id="clear-filters">Clear search & filters</button></div>`;updateMarkers()}
function updateMarkers(){if(!map)return;const ids=results().map(c=>c.id);clubs.forEach(c=>{const selected=c.id===active;const html=`<div class="club-pin ${selected?'selected':''}"><span class="pin-circle">${selected?'✧':'◇'}</span><span class="pin-label">${c.name}</span></div>`;markers[c.id].setIcon(L.divIcon({className:'',html,iconSize:[1,1],iconAnchor:[0,0]}));if(ids.includes(c.id)){if(!map.hasLayer(markers[c.id]))markers[c.id].addTo(map)}else markers[c.id].remove();markers[c.id].setZIndexOffset(selected?1000:0)})}
function select(id,fly=true){active=id;render();if(map&&fly){const c=current();map.flyTo([c.lat+(innerWidth<701?-.023:0),c.lng],map.getZoom(),{duration:1.1})}}
function previewClub(id){if(!clubs.some(c=>c.id===id))return;active=id;$$('[data-tile]').forEach(tile=>tile.classList.toggle('active',tile.dataset.tile===id));updateMarkers();if(map){const c=current();map.panTo([c.lat,c.lng],{animate:true,duration:.45})}}
function initMap(){if(!window.L){$('#map').innerHTML='<p class="map-error">The map could not load. You can still explore all four clubs from the collection.</p>';return}map=L.map('map',{zoomControl:false,scrollWheelZoom:false}).setView([innerWidth<701?25.78:25.822,-80.151],innerWidth<701?11:12);const tiles=L.tileLayer('https://server.arcgisonline.com/ArcGIS/rest/services/World_Street_Map/MapServer/tile/{z}/{y}/{x}',{attribution:'Tiles &copy; Esri &mdash; Esri, HERE, Garmin, FAO, NOAA, USGS, &copy; OpenStreetMap contributors, and the GIS User Community',maxZoom:16,crossOrigin:true});tiles.on('tileerror',()=>$('#map').classList.add('tile-load-error'));tiles.addTo(map);L.control.zoom({position:'topright'}).addTo(map);clubs.forEach(c=>{markers[c.id]=L.marker([c.lat,c.lng],{title:c.name,keyboard:true}).addTo(map).on('click',()=>select(c.id))});updateMarkers()}
function open(view,html){$('#overlay').dataset.view=view;$('#dialog-content').innerHTML=html;if(!$('#overlay').open)$('#overlay').showModal();$('#overlay').scrollTop=0;$$('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===view))}
function close(){ $('#overlay').close();$('#overlay').dataset.view='';$$('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view==='discover'))}
function detail(id){const c=clubs.find(x=>x.id===id);select(id);open('detail',`<article class="detail"><button class="detail-back" data-view="discover">← Back to discovery</button><div class="detail-visual"><img src="${c.image}" alt="${c.name}"></div><div class="detail-copy"><div class="eyebrow">THE OSTRA COLLECTION / MIAMI</div><h1>${c.name}</h1><div class="meta">${c.area} · ${c.type}</div><p>${c.description}</p><h3>A sense of place</h3><p>${c.atmosphere}</p><div class="amenities">${c.amenities.map(a=>`<span>${a}</span>`).join('')}</div><h3>Membership & access</h3><p>${c.info}</p>${c.gallery?`<div class="gallery"><img src="${c.image}" alt="${c.name} setting"><img src="${c.gallery}" alt="Another view of ${c.name}"></div>`:''}<h3>On the coast</h3><p>${c.address}</p><a class="location-link" href="https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(c.name+' '+c.address)}" target="_blank" rel="noopener">View location & directions ↗</a><div class="detail-links"><a class="primary" href="${c.url}" target="_blank" rel="noopener">Explore official club ↗</a>${saveButton(c)}</div><p class="disclaimer">Club information from the official website. Membership and access are subject to the club’s current policies.</p></div></article>`)}
function showSaved(){open('saved',`<section class="panel"><div class="eyebrow">YOUR PERSONAL COLLECTION</div><h1>Places to come back to.</h1><p>Your saved clubs, kept on this device.</p>${saved.length?`<div class="saved-grid">${saved.map(id=>{const c=clubs.find(x=>x.id===id);return `<article class="saved-card"><img src="${c.image}" alt="${c.name}"><h2>${c.name}</h2><p class="meta">${c.area} · ${c.type}</p><div><button class="primary" data-detail="${id}">Explore club ↗</button>${saveButton(c)}</div></article>`}).join('')}</div>`:`<div class="empty"><span>♡</span><h2>Your next favorite awaits.</h2><p>Save a club that catches your eye. We’ll keep it here.</p><button class="primary" data-view="discover">Discover the collection ↗</button></div>`}</section>`)}
let messages=[{text:'Welcome to Ostra. Tell me what you have in mind — a quiet beach, a creative crowd, or somewhere to unwind.',user:false}];
function chat(){open('concierge',`<section class="panel chat-panel"><div class="chat-heading"><img class="chat-photo" src="assets/ostra-concierge.png" alt="Ostra concierge"><div><h1>Your Ostra AI concierge</h1><p>Personal recommendations from the Ostra collection.</p></div></div><div class="messages" aria-live="polite"></div><div class="suggestions"><button data-request="Find beach clubs near Miami Beach">Beach clubs near Miami Beach</button><button data-request="Somewhere quiet and secluded">Somewhere quiet</button><button data-request="A creative social crowd">A creative crowd</button></div><form class="chat-form"><input aria-label="Message your concierge" placeholder="What kind of place feels like you?" required maxlength="500"><button aria-label="Send message">↑</button></form><p class="disclaimer">An automated guide to our four-club collection. For availability and membership, contact the club directly.</p></section>`);renderMessages();$('.chat-form').onsubmit=e=>{e.preventDefault();ask($('.chat-form input').value);$('.chat-form input').value=''}}
function renderMessages(){const el=$('.messages');if(!el)return;el.innerHTML=messages.map(m=>`<div class="message ${m.user?'user':''}">${esc(m.text)}${m.id?`<br><button class="primary" data-detail="${m.id}">Explore ${clubs.find(c=>c.id===m.id).name} ↗</button>`:''}</div>`).join('')+(chatBusy?'<div class="message">Finding clubs…</div>':'');el.scrollTop=el.scrollHeight}
function ask(value){const q=value.trim();if(!q||chatBusy)return;messages.push({text:q,user:true});chatBusy=true;renderMessages();setTimeout(()=>{const t=q.toLowerCase();let c;if(/surf|historic|glamour/.test(t))c=clubs[2];else if(/soho|creativ|social|crowd/.test(t))c=clubs[3];else if(/fisher|quiet|seclud|island|golf/.test(t))c=clubs[0];else if(/bath|beach|miami/.test(t))c=clubs[1];else if(/spa|wellness|gym/.test(t))c=clubs[3];if(c){filter='All clubs';$('#nav-search').value='';$$('[data-filter]').forEach(b=>b.classList.toggle('active',b.dataset.filter===filter));select(c.id);messages.push({text:`${c.name} is worth a closer look. ${c.description} I’ve selected it on your map. ${c.membership}.`,id:c.id})}else{messages.push({text:'I can help compare Fisher Island Club, The Bath Club, The Surf Club, and Soho Beach House. Try “a quiet beach”, “wellness”, or a club name. For booking or live availability, please contact the club.'})}chatBusy=false;renderMessages()},900)}
function profile(){open('profile',`<section class="panel"><div class="eyebrow">YOUR OSTRA SETTINGS</div><h1>Make Ostra yours.</h1><p>Your settings and saved clubs stay on this device.</p><div class="setting"><div><strong>Your collection</strong><small>${saved.length} ${saved.length===1?'club':'clubs'} saved for another day</small></div><button class="primary" data-view="saved">View saved ↗</button></div><label class="setting"><span><strong>Default club view</strong><small>Choose which clubs appear when Ostra opens</small></span><select id="interest">${['All clubs','Beach','Social','Wellness'].map(x=>`<option ${prefs.interest===x?'selected':''}>${x}</option>`).join('')}</select></label><label class="setting"><span><strong>Concierge suggestions</strong><small>Show suggested requests in AI conversations</small></span><input type="checkbox" id="suggestion-setting" ${prefs.suggestions!==false?'checked':''}></label><label class="setting"><span><strong>Local notifications</strong><small>Show brief confirmations when settings change</small></span><input type="checkbox" id="notification-setting" ${prefs.notifications?'checked':''}></label><div class="setting"><span><strong>Your privacy</strong><small>Clear saved clubs and settings from this device.</small></span><button id="clear-data" style="text-decoration:underline;font-size:13px">Clear data</button></div><p class="disclaimer">No account or email address is required. Ostra does not submit reservations or membership applications.</p></section>`);$('#interest').onchange=e=>{prefs.interest=e.target.value;prefs.settingsVersion=2;filter=prefs.interest;persist();$$('[data-filter]').forEach(b=>b.classList.toggle('active',b.dataset.filter===filter));render();toast('Default club view updated')};$('#suggestion-setting').onchange=e=>{prefs.suggestions=e.target.checked;prefs.settingsVersion=2;persist();toast('Concierge suggestions updated')};$('#notification-setting').onchange=e=>{prefs.notifications=e.target.checked;prefs.settingsVersion=2;persist();toast(prefs.notifications?'Local confirmations enabled':'Local confirmations disabled')};$('#clear-data').onclick=()=>{if(confirm('Clear saved clubs and settings from this device?')){saved=[];prefs={interest:'All clubs',notifications:false,suggestions:true,settingsVersion:2};filter='All clubs';persist();$$('[data-filter]').forEach(b=>b.classList.toggle('active',b.dataset.filter===filter));render();profile();toast('Local data cleared')}}}
document.addEventListener('click',e=>{let b=e.target.closest('[data-save]');if(b)return save(b.dataset.save);b=e.target.closest('[data-select]');if(b)return select(b.dataset.select);b=e.target.closest('[data-detail]');if(b)return detail(b.dataset.detail);b=e.target.closest('[data-request]');if(b)return ask(b.dataset.request);b=e.target.closest('[data-filter]');if(b){filter=b.dataset.filter;$$('[data-filter]').forEach(x=>x.classList.toggle('active',x===b));render();return}b=e.target.closest('[data-view]');if(b){const v=b.dataset.view;if(v==='discover')close();if(v==='saved')showSaved();if(v==='concierge'){chat();if(prefs.suggestions===false)$('.suggestions').hidden=true}if(v==='profile')profile()}if(e.target.id==='clear-filters'){filter='All clubs';$('#nav-search').value='';$$('[data-filter]').forEach(x=>x.classList.toggle('active',x.dataset.filter===filter));render()}});
document.addEventListener('pointerover',e=>{if(innerWidth<=700)return;const tile=e.target.closest('[data-tile]');if(tile&&e.relatedTarget!==tile&&!tile.contains(e.relatedTarget))previewClub(tile.dataset.tile)});document.addEventListener('focusin',e=>{const tile=e.target.closest('[data-tile]');if(tile)previewClub(tile.dataset.tile)});
$('.close').onclick=close;$('#overlay').addEventListener('cancel',e=>{e.preventDefault();close()});$('#overlay').addEventListener('click',e=>{if(e.target===$('#overlay'))close()});$('#nav-search').oninput=render;$('#reset-map').onclick=()=>{if(map&&results().length)map.fitBounds(clubs.filter(c=>results().includes(c)).map(c=>[c.lat,c.lng]),{padding:innerWidth<701?[60,120]:[100,100],maxZoom:12})};$('#sheet-handle').onclick=()=>$('.discovery').classList.toggle('expanded');document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key==='k'){e.preventDefault();close();$('#nav-search').focus()}});
let touchStart;$('.discovery').addEventListener('touchstart',e=>{touchStart={x:e.touches[0].clientX,y:e.touches[0].clientY,target:e.target}},{passive:true});$('.discovery').addEventListener('touchend',e=>{if(!touchStart)return;const dx=e.changedTouches[0].clientX-touchStart.x,dy=e.changedTouches[0].clientY-touchStart.y;if(Math.abs(dx)>65&&Math.abs(dx)>Math.abs(dy)&&touchStart.target.closest('.club-tile')){const list=results();select(list[(list.findIndex(c=>c.id===active)+(dx<0?1:-1)+list.length)%list.length].id)}else if(Math.abs(dy)>55&&Math.abs(dy)>Math.abs(dx)&&(touchStart.target.closest('#sheet-handle')||(!$('.discovery').classList.contains('expanded')&&dy<0))){$('.discovery').classList.toggle('expanded',dy<0)}touchStart=null},{passive:true});
filter=['All clubs','Beach','Social','Wellness'].includes(prefs.interest)?prefs.interest:'All clubs';$$('[data-filter]').forEach(b=>b.classList.toggle('active',b.dataset.filter===filter));render();initMap();







